/* ════════════════════════════════════════════════════════════════
   ANIMSA — Sesli & yazılı hatırlatıcı (iPhone PWA)  ·  sürüm 1.0.0
   Tek dosya Cloudflare Worker (module biçimi). Bu dosyayı Cloudflare
   panelindeki düzenleyiciye olduğu gibi yapıştırın.
   Gerekenler: "KV" adlı KV bağlaması + her dakika cron (* * * * *).
   Ayrıntılar: KURULUM.md
   Bu dosya tools/build.mjs ile src/ klasöründen üretilir; elle düzenlemeyin.
   ════════════════════════════════════════════════════════════════ */

/* ════════════════════════════════════════════════════════════════
   ANIMSA — Türkçe anlama motoru (kural tabanlı, internetsiz)
   parse(metin, şimdi) → { zaman, görev, saatBelirtildiMi, güven, ... }
   Bu dosya hem tarayıcıda (derlemede gömülür) hem Node testlerinde çalışır.
   ════════════════════════════════════════════════════════════════ */

const TR = 'tr-TR';

/* ── Sözlükler ─────────────────────────────────────────────── */
const UNITS = { bir: 1, iki: 2, 'üç': 3, 'dört': 4, 'dörd': 4, 'beş': 5, 'altı': 6, yedi: 7, sekiz: 8, dokuz: 9 };
const TENS = { on: 10, yirmi: 20, otuz: 30, 'kırk': 40, elli: 50 };
// Sayı sözcüklerinin alabileceği ekler (uzundan kısaya)
const NUM_SUFFIXES = ['ında', 'inde', 'unda', 'ünde', 'sında', 'sinde', 'sinda', 'sına', 'sine', 'yı', 'yi', 'yu', 'yü', 'ya', 'ye', 'da', 'de', 'ta', 'te', 'dan', 'den', 'tan', 'ten', 'sı', 'si', 'su', 'sü', 'a', 'e', 'ı', 'i', 'u', 'ü'];
const LOC = new Set(['de', 'da', 'te', 'ta']); // bulunma eki: "7'de", "yedide"
const DAT = new Set(['a', 'e', 'ya', 'ye']); // yönelme eki: "bire", "ona"
const ACC = new Set(['ı', 'i', 'u', 'ü', 'yı', 'yi', 'yu', 'yü']); // belirtme eki: "dokuzu"

const WEEKDAYS = [ // uzun adlar önce (cumartesi > cuma, pazartesi > pazar)
  ['pazartesi', 1], ['cumartesi', 6], ['çarşamba', 3], ['perşembe', 4], ['salı', 2], ['cuma', 5], ['pazar', 0]
];
const WD_SUFFIX = new Set(['', 'ya', 'ye', 'a', 'e', 'da', 'de', 'ta', 'te', 'yı', 'yi', 'ı', 'i', 'ki', 'dan', 'den', 'ye kadar']);
const MONTHS = ['ocak', 'şubat', 'mart', 'nisan', 'mayıs', 'haziran', 'temmuz', 'ağustos', 'eylül', 'ekim', 'kasım', 'aralık'];
const MONTH_SUFFIX = new Set(['', 'ta', 'da', 'te', 'de', 'ın', 'in', 'un', 'ün', 'ında', 'inde', 'unda', 'ünde', 'a', 'e', 'ya', 'ye']);

// Gün bölümleri → [anahtar, varsayılan saat]
const PERIODS = {
  sabah: 'sabah', sabahleyin: 'sabah', sabaha: 'sabah', sabahki: 'sabah', 'sabahın': 'sabah',
  'öğle': 'oglen', 'öğlen': 'oglen', 'öğleyin': 'oglen', 'öğlene': 'oglen', 'öğleye': 'oglen',
  ikindi: 'ikindi', ikindiye: 'ikindi', ikindide: 'ikindi',
  'akşam': 'aksam', 'akşamleyin': 'aksam', 'akşama': 'aksam', 'akşamüstü': 'aksamustu', 'akşamüzeri': 'aksamustu', 'akşamki': 'aksam', 'akşamın': 'aksam',
  gece: 'gece', geceleyin: 'gece', geceye: 'gece', 'gecenin': 'gece'
};
const PERIOD_DEFAULT = { sabah: 9, oglen: 12, ogleden: 15, ikindi: 16, aksamustu: 18, aksam: 20, gece: 22 };

// Dolgu sözcükleri: kenarlardan temizlenir
const EDGE_FILLERS = new Set(['saat', 'bana', 'beni', 'bunu', 'şunu', 'lütfen', 'kur', 'de', 'da', 've', 'için', 'olarak', 'sonra', 'tarihinde', 'günü', 'gün', 'hatırlatıcı', 'hatırlatma', 'hatırlatması', 'alarm', 'kadar', 'ile', 'ki', 'mi', 'mı']);
// Tek başına bir yan cümle oluşturduklarında atılan rica sözcükleri ("bana bunu hatırlatır mısın")
const META_WORDS = new Set(['bana', 'beni', 'bunu', 'şunu', 'onu', 'bunları', 'lütfen', 'unutma', 'unutmayayım', 'unutturma', 'sakın', 'tamam', 'olur', 'mu', 'mı', 'mi', 'mü', 'musun', 'mısın', 'misin', 'de', 'da', 'ki', 've', 'yap', 'kur', 'alarm', 'not', 'al', 'et', 'eder', 'edebilir', 'etsene', 'hadi', 'acaba', 'benim', 'için', 'teşekkürler', 'sağol', 'sağ', 'ol']);
// Her yerden silinen sözcükler
const ANY_FILLERS = new Set(['hatırlat', 'hatırlatır', 'hatırlatsana', 'hatırlatırmısın', 'hatırlatırsın', 'hatırlatıver', 'mısın', 'misin', 'lütfen', 'hatırlatıcı', 'hatırlatıcısı', 'hatırlatma', 'hatırlatmayı', 'unutma', 'unutturma', 'kur']);

/* ── Yardımcılar ───────────────────────────────────────────── */
function lower(s) { return String(s).toLocaleLowerCase(TR); }

/** Bir sözcüğü karşılaştırma için normalleştirir. */
function norm(raw) {
  let s = lower(raw);
  s = s.replace(/[’‘'`´"“”«»]/g, '');          // kesme ve tırnaklar
  s = s.replace(/^[(\[{,;!?¡¿…-]+/, '').replace(/[)\]},;!?…]+$/, '');
  s = s.replace(/\.+$/, '');                      // sondaki nokta
  return s;
}

/** Ekli sözcükten kök + ek ayırır (kök sözlükte varsa). */
function splitSuffix(tok, dict) {
  if (Object.prototype.hasOwnProperty.call(dict, tok)) return { base: tok, suffix: '' };
  for (const suf of NUM_SUFFIXES) {
    if (tok.length > suf.length && tok.endsWith(suf)) {
      const base = tok.slice(0, -suf.length);
      if (Object.prototype.hasOwnProperty.call(dict, base)) return { base, suffix: suf };
    }
  }
  return null;
}

const ALLNUM = Object.assign({}, UNITS, TENS, { 'yarım': 0.5 });

/**
 * i konumundaki sözcüklerden bir sayı okur.
 * Desteklenen: "7", "14:30", "7de", "yedi", "yedide", "on iki", "onikide", "yirmi beş", "yarım".
 * Dönüş: { val, min (varsa dakika), len, suffix, word (sözcükle mi yazıldı), colon }
 */
function readNumber(T, i) {
  const t = T[i];
  if (!t) return null;
  const n = t.n;
  // Rakam: 7, 14:30, 14.30, 7de, 14:00te, 1,5
  let m = n.match(/^(\d{1,2})(?:([:.,])(\d{1,2}))?([a-zçğıöşü]*)$/);
  if (m) {
    const r = { val: +m[1], len: 1, suffix: m[4] || '', word: false, sep: m[2] || '', lead0: m[1].length === 2 && m[1][0] === '0' };
    if (m[3] !== undefined) { r.min = m[3].length === 2 ? +m[3] : null; r.frac = +('0.' + m[3]); }
    return r;
  }
  // Sözcük: önce iki sözcüklü bileşik (on iki, yirmi beş)
  const a = splitSuffix(n, ALLNUM);
  if (a && TENS[a.base] && !a.suffix && T[i + 1]) {
    const b = splitSuffix(T[i + 1].n, UNITS);
    if (b) return { val: TENS[a.base] + UNITS[b.base], len: 2, suffix: b.suffix, word: true };
  }
  if (a) return { val: ALLNUM[a.base], len: 1, suffix: a.suffix, word: true };
  // Bitişik bileşik: onbir, yirmibeş, onikide
  for (const ten of Object.keys(TENS)) {
    if (n.startsWith(ten) && n.length > ten.length) {
      const b = splitSuffix(n.slice(ten.length), UNITS);
      if (b) return { val: TENS[ten] + UNITS[b.base], len: 1, suffix: b.suffix, word: true };
    }
  }
  return null;
}

function isBucuk(tok) { return tok && /^buçu(k|ğ)(ta|a|u|tan)?$/.test(tok.n); }
function bucukSuffix(tok) { const m = tok.n.match(/^buçu(?:k|ğ)(ta|a|u|tan)?$/); return m ? (m[1] || '') : ''; }

function startOfDay(d) { return new Date(d.getFullYear(), d.getMonth(), d.getDate()); }
function addDays(d, n) { return new Date(d.getFullYear(), d.getMonth(), d.getDate() + n, d.getHours(), d.getMinutes()); }
function atTime(day, h, m) { return new Date(day.getFullYear(), day.getMonth(), day.getDate(), h, m, 0, 0); }

/* ── Ana fonksiyon ─────────────────────────────────────────── */
function parse(metin, simdi) {
  const now = simdi instanceof Date ? new Date(simdi.getTime()) : new Date(simdi == null ? Date.now() : simdi);
  const text = String(metin == null ? '' : metin)
    .replace(/\s+/g, ' ')
    .replace(/(\d)\s*([:.])\s*(\d{2})\b/g, '$1$2$3') // "14 : 30" → "14:30"
    .trim();
  const T = text ? text.split(' ').map(raw => ({ raw, n: norm(raw), used: false })) : [];
  const use = (i, len) => { for (let k = i; k < i + len && k < T.length; k++) T[k].used = true; };
  const free = i => T[i] && !T[i].used;

  let relMs = null;          // dakika/saat cinsinden göreli süre
  let relDays = null;        // gün/hafta/ay cinsinden göreli süre
  let date = null;           // { kind: 'offset'|'weekday'|'abs'|'monthEnd', ... }
  let period = null;         // sabah | oglen | ogleden | ikindi | aksam | aksamustu | gece
  let clock = null;          // { h, m }
  let midnight = false;      // "gece yarısı"

  /* ── 1) Göreli süreler: "20 dk sonra", "bir buçuk saat sonra", "yarım saat içinde", "bir saate" ── */
  const UNIT_RE = /^(saniye|sn|dakika|dakka|dak|dk|saat|sa|gün|hafta|ay)(ya|ye|a|e|lık|lik)?$/;
  const unitOf = w => {
    const m = w.match(UNIT_RE); if (!m) return null;
    const u = m[1];
    const k = (u === 'saniye' || u === 'sn') ? 'sn' : (u === 'saat' || u === 'sa') ? 'saat' : (u === 'gün' || u === 'hafta' || u === 'ay') ? u : 'dk';
    return { unit: k, dative: m[2] === 'a' || m[2] === 'e' || m[2] === 'ya' || m[2] === 'ye' };
  };
  for (let i = 0; i < T.length; i++) {
    if (!free(i)) continue;
    let j = i, total = { ms: 0, days: 0 }, parts = 0, terminal = false;
    while (j < T.length) {
      let qty = null, qlen = 0;
      const tok = T[j];
      // "20dk", "2saat" bitişik yazım
      const glued = tok.n.match(/^(\d+(?:[.,]\d+)?)(dk|dakika|sa|saat|gün)(ya|ye|a|e)?$/);
      if (glued) {
        const u = unitOf(glued[2] + (glued[3] || ''));
        const q = parseFloat(glued[1].replace(',', '.'));
        addDur(total, q, u.unit); parts++; j++;
        if (u.dative) { terminal = true; break; }
        continue;
      }
      if (tok.n === 'çeyrek') { qty = 0.25; qlen = 1; }
      else {
        const num = readNumber(T, j);
        if (num && !num.suffix && num.val > 0 && (!num.sep || num.sep === '.' || num.sep === ',')) {
          qty = num.sep ? num.val + (num.frac || 0) : num.val; qlen = num.len;
          if (num.word && num.val === 0.5) qty = 0.5; // yarım
          if (isBucuk(T[j + qlen]) && !bucukSuffix(T[j + qlen])) { qty += 0.5; qlen++; }
        }
      }
      if (qty == null) break;
      const ut = T[j + qlen] && unitOf(T[j + qlen].n);
      if (!ut) break;
      // "saat 2" (saat kalıbı) ile karışmasın: sayı + birim sırası şart
      addDur(total, qty, ut.unit); parts++;
      j += qlen + 1;
      if (ut.dative) { terminal = true; break; }
      // "1 saat 20 dakika sonra" gibi zincirleme
    }
    if (!parts) continue;
    const nx = T[j] && T[j].n;
    if (!terminal && (nx === 'sonra' || nx === 'içinde' || nx === 'içerisinde' || nx === 'sonrası' || nx === 'zarfında')) { terminal = true; j++; }
    if (!terminal && nx === 'geçince') { terminal = true; j++; }
    if (!terminal) continue;
    use(i, j - i);
    if (total.ms) relMs = (relMs || 0) + total.ms;
    if (total.days) relDays = (relDays || 0) + total.days;
    i = j - 1;
  }
  function addDur(acc, q, unit) {
    if (unit === 'sn') acc.ms += q * 1000;
    else if (unit === 'dk') acc.ms += q * 60000;
    else if (unit === 'saat') acc.ms += q * 3600000;
    else if (unit === 'gün') acc.days += Math.round(q);
    else if (unit === 'hafta') acc.days += Math.round(q * 7);
    else if (unit === 'ay') acc.days += Math.round(q * 30);
  }

  /* ── 2) Tarihler ── */
  for (let i = 0; i < T.length; i++) {
    if (!free(i)) continue;
    const n = T[i].n, n1 = T[i + 1] && free(i + 1) ? T[i + 1].n : '';
    if (n === 'bugün' || n === 'bugun') { date = { kind: 'offset', days: 0, today: true }; use(i, 1); continue; }
    if (n === 'yarından' && n1 === 'sonra') { date = { kind: 'offset', days: 2 }; use(i, 2); continue; }
    if (n === 'yarın' || n === 'yarin') { date = { kind: 'offset', days: 1 }; use(i, 1); continue; }
    if (n === 'öbürgün' || n === 'öbür' && (n1 === 'gün' || n1 === 'güne')) { date = { kind: 'offset', days: 2 }; use(i, n === 'öbürgün' ? 1 : 2); continue; }
    if (n === 'ertesi' && (n1 === 'gün' || n1 === 'güne')) { date = { kind: 'offset', days: 2 }; use(i, 2); continue; }
    // "haftaya salı", "gelecek hafta cuma", "haftaya"
    let nextWeek = false, k = i;
    if (n === 'haftaya') { nextWeek = true; k = i + 1; }
    else if ((n === 'gelecek' || n === 'önümüzdeki' || n === 'sonraki') && n1 === 'hafta') { nextWeek = true; k = i + 2; }
    else if (n === 'bu' && n1) { k = i + 1; }
    const wd = T[k] && free(k) ? weekdayOf(T[k].n) : null;
    if (wd != null) {
      let len = k - i + 1;
      if (T[k + 1] && /^gün(ü|ün|e|ünde)?$/.test(T[k + 1].n)) len++;
      date = { kind: 'weekday', wd, nextWeek };
      use(i, len); continue;
    }
    if (n === 'bu' && n1 && PERIODS[n1]) { date = { kind: 'offset', days: 0, today: true }; use(i, 1); continue; }
    if (nextWeek) { date = { kind: 'offset', days: 7 }; use(i, k - i); continue; }
    // "ayın 20'si", "ayın 20sinde", "ayın sonunda"
    if (n === 'ayın' && T[i + 1]) {
      if (/^son(u|unda|una)$/.test(n1)) { date = { kind: 'monthEnd' }; use(i, 2); continue; }
      const num = readNumber(T, i + 1);
      if (num && !num.word && num.val >= 1 && num.val <= 31) { date = { kind: 'abs', d: num.val, m: null }; use(i, 2); continue; }
    }
    // "3 Aralık", "3 aralıkta", "3 Aralık 2027"
    const num = readNumber(T, i);
    if (num && num.val >= 1 && num.val <= 31 && num.min == null && !num.suffix && T[i + 1]) {
      const mo = monthOf(T[i + 1].n);
      if (mo != null) {
        let len = 2, y = null;
        const ym = T[i + 2] && T[i + 2].n.match(/^(20\d\d)([a-zçğıöşü]*)$/);
        if (ym) { y = +ym[1]; len = 3; }
        date = { kind: 'abs', d: num.val, m: mo, y }; use(i, len); continue;
      }
    }
    // "15/12", "15/12/2026", "15.12" (soneksiz ve "saat" öncesi değilse tarih)
    const dm = n.match(/^(\d{1,2})([./-])(\d{1,2})(?:\2(\d{2,4}))?([a-zçğıöşü]*)$/);
    if (dm) {
      const d = +dm[1], mo = +dm[3], sep = dm[2];
      const prevSaat = i > 0 && T[i - 1].n === 'saat';
      const looksDate = sep === '/' || sep === '-' || dm[4] || (!dm[5] && !prevSaat && mo >= 1 && mo <= 12 && !(T[i + 1] && /^(buçuk|sonra)/.test(T[i + 1].n)));
      if (looksDate && d >= 1 && d <= 31 && mo >= 1 && mo <= 12) {
        let y = dm[4] ? +dm[4] : null; if (y != null && y < 100) y += 2000;
        date = { kind: 'abs', d, m: mo - 1, y }; use(i, 1); continue;
      }
    }
  }
  function weekdayOf(w) {
    for (const [name, idx] of WEEKDAYS) {
      if (w.startsWith(name) && WD_SUFFIX.has(w.slice(name.length))) return idx;
    }
    return null;
  }
  function monthOf(w) {
    for (let k = 0; k < MONTHS.length; k++) {
      if (w.startsWith(MONTHS[k]) && MONTH_SUFFIX.has(w.slice(MONTHS[k].length))) return k;
    }
    return null;
  }

  /* ── 3) Gün bölümleri ve saatler ── */
  // Bir sayının saat olarak okunması (buçuk dahil). Dönüş: { h, m, len } | null
  const readClock = (i, needSuffix) => {
    const num = readNumber(T, i);
    if (!num || !free(i)) return null;
    if (num.word && num.val === 0.5) { // "yarımda" = 12:30
      if (LOC.has(num.suffix) || !needSuffix) return { h: 12, m: 30, len: num.len, suffix: num.suffix };
      return null;
    }
    let h = num.val, m = 0, len = num.len, suffix = num.suffix;
    if (num.sep === ':' || num.sep === '.') {
      if (num.min == null) return null;
      m = num.min;
    } else if (num.sep) return null;
    // "yedi buçukta", "7 buçukta"
    if (!suffix && num.min == null && isBucuk(T[i + len]) && free(i + len)) {
      suffix = bucukSuffix(T[i + len]); m = 30; len++;
    } else if (num.word && !suffix && T[i + len] && free(i + len) && !num.sep) {
      // "saat on dört otuzda" → dakika sözcükle
      const mm = readNumber(T, i + len);
      if (mm && mm.word && mm.val >= 10 && mm.val < 60 && (mm.val % 10 === 0 || mm.len === 2) && needSuffix === false) {
        m = mm.val; suffix = mm.suffix; len += mm.len;
      }
    }
    if (needSuffix && !LOC.has(suffix) && num.sep !== ':') return null;
    if (h > 24 || m > 59 || !Number.isInteger(h)) return null;
    if (h === 24) h = 0;
    // ayrık yazılmış ek: "15:00 de"
    if (!suffix && T[i + len] && free(i + len) && LOC.has(T[i + len].n)) len++;
    return { h, m, len, suffix, literal: !!num.lead0 && num.sep === ':' };
  };

  for (let i = 0; i < T.length; i++) {
    if (!free(i)) continue;
    const n = T[i].n, n1 = T[i + 1] ? T[i + 1].n : '';
    // "gece yarısı"
    if (n === 'gece' && /^yarısı(na|nda)?$/.test(n1)) { midnight = true; period = 'gece'; use(i, 2); continue; }
    // "öğleden sonra"
    if (n === 'öğleden' && n1 === 'sonra') { period = 'ogleden'; use(i, 2); tryClockAfter(i + 2); continue; }
    if (PERIODS[n]) {
      // "öğle yemeği", "akşam namazı": sözcük görevin parçası, yine de gün bölümü bilgisini al
      if (/^(yemeğ|yemek|namaz|ara(sı|sında)?$|mesai|vardiya|haber|yürüyüş|kahvaltı)/.test(n1)) { if (!period) period = PERIODS[n]; continue; }
      period = PERIODS[n]; use(i, 1); tryClockAfter(i + 1); continue;
    }
    // "saat 14:00", "saat yedide", "saat 3"
    if (n === 'saat' || n === 'saatte' || n === 'saati') {
      if (tryGeceVar(i + 1, i)) continue;
      const c = readClock(i + 1, false);
      if (c) { clock = { h: c.h, m: c.m, literal: c.literal }; use(i, 1 + c.len); i += c.len; continue; }
    }
    // "dokuzu çeyrek geçe", "ona çeyrek var"
    if (tryGeceVar(i, i)) continue;
    // "14:30", "14:30da", "7de", "yedide"
    const num = readNumber(T, i);
    if (num && (num.sep === ':' || ((num.sep === '.') && (LOC.has(num.suffix) || (i > 0 && T[i - 1].n === 'saat'))) || LOC.has(num.suffix) || isBucuk(T[i + num.len]) && (LOC.has(bucukSuffix(T[i + num.len]))))) {
      const c = readClock(i, num.sep !== ':');
      if (c && clock == null) { clock = { h: c.h, m: c.m, literal: c.literal }; use(i, c.len); i += c.len - 1; continue; }
    }
  }
  function tryClockAfter(i) {
    if (clock) return;
    let k = i;
    if (T[k] && free(k) && T[k].n === 'saat') k++;
    if (tryGeceVar(k, i)) return;
    const c = readClock(k, false);
    if (c) { clock = { h: c.h, m: c.m, literal: c.literal }; use(i, k - i + c.len); }
  }
  // "X-i Y geçe" ve "X-e Y var/kala"
  function tryGeceVar(i, from) {
    const hn = readNumber(T, i);
    if (!hn || !free(i) || hn.sep) return false;
    let k = i + hn.len, mins = null, mlen = 0;
    if (T[k] && T[k].n === 'çeyrek') { mins = 15; mlen = 1; }
    else { const mn = readNumber(T, k); if (mn && !mn.suffix && !mn.sep && mn.val > 0 && mn.val < 60) { mins = mn.val; mlen = mn.len; } }
    if (mins == null || !T[k + mlen]) return false;
    const w = T[k + mlen].n;
    if (w === 'geçe' && (ACC.has(hn.suffix) || !hn.suffix)) {
      clock = { h: hn.val % 24, m: mins }; use(from, k + mlen + 1 - from); return true;
    }
    if ((w === 'var' || w === 'kala') && (DAT.has(hn.suffix) || !hn.suffix)) {
      clock = { h: (hn.val + 23) % 24, m: 60 - mins }; use(from, k + mlen + 1 - from); return true;
    }
    return false;
  }

  /* ── 4) Zamanı hesapla ── */
  let zaman, saatBelirtildiMi = true, rolled = false, guven;
  const today = startOfDay(now);

  if (relMs != null && relDays == null && !date) {
    // Tam dakikaya yuvarla: zamanlayıcı dakika başında çalışır, ekranda yazan dakika = bildirimin geleceği dakika
    zaman = roundToMinute(now.getTime() + relMs, now.getTime());
    guven = 0.95;
  } else {
    // Gün tabanı
    let day = today, implicitToday = true, kind = 'today';
    if (relDays != null) { day = addDays(today, relDays); implicitToday = false; kind = 'rel'; }
    if (date) {
      if (date.kind === 'offset') { day = addDays(today, date.days); implicitToday = !!date.today || date.days === 0; kind = date.days ? 'offset' : 'today'; }
      else if (date.kind === 'weekday') {
        let diff = (date.wd - now.getDay() + 7) % 7;
        if (date.nextWeek) {
          // haftaya: bir sonraki takvim haftası (Pazartesi başlangıçlı)
          const mondayIdx = d => (d + 6) % 7;
          diff = 7 - mondayIdx(now.getDay()) + mondayIdx(date.wd);
        }
        day = addDays(today, diff); implicitToday = false; kind = date.nextWeek ? 'nextweek' : 'weekday';
      } else if (date.kind === 'abs') {
        const y = date.y || now.getFullYear();
        const mo = date.m == null ? now.getMonth() : date.m;
        day = new Date(y, mo, Math.min(date.d, new Date(y, mo + 1, 0).getDate()));
        implicitToday = false; kind = date.m == null ? 'monthday' : (date.y ? 'absy' : 'abs');
      } else if (date.kind === 'monthEnd') {
        day = new Date(now.getFullYear(), now.getMonth() + 1, 0); implicitToday = false; kind = 'monthend';
      }
    }
    if (relMs != null) { // "3 gün sonra" + "2 saat sonra" birleşimi gibi nadir durumlar
      zaman = new Date(day.getTime() + (now.getTime() - today.getTime()) + relMs);
      guven = 0.8;
    } else {
      let h, m;
      if (midnight) { h = 0; m = 0; day = addDays(day, 1); }
      else if (clock) {
        ({ h, m } = clock);
        const r = clock.literal ? { h } : resolveHour(h, period, implicitToday);
        h = r.h; if (r.nextDay) day = addDays(day, 1);
      } else if (period) {
        h = PERIOD_DEFAULT[period]; m = 0;
        saatBelirtildiMi = period === 'oglen';
      } else { h = 9; m = 0; saatBelirtildiMi = false; }
      zaman = atTime(day, h, m);

      // Geçmişte kaldıysa ileri at
      if (zaman.getTime() <= now.getTime()) {
        if (clock && !clock.literal && !period && implicitToday && clock.h >= 7 && clock.h <= 11) {
          const pm = atTime(day, clock.h + 12, clock.m); // önce akşam dene
          if (pm.getTime() > now.getTime()) zaman = pm; else { zaman = addDays(zaman, 1); rolled = true; }
        } else if (implicitToday || kind === 'offset' && date && date.days === 0) { zaman = addDays(zaman, 1); rolled = true; }
        else if (kind === 'weekday') zaman = addDays(zaman, 7);
        else if (kind === 'abs') zaman = new Date(zaman.getFullYear() + 1, zaman.getMonth(), zaman.getDate(), zaman.getHours(), zaman.getMinutes());
        else if (kind === 'monthday') zaman = new Date(zaman.getFullYear(), zaman.getMonth() + 1, zaman.getDate(), zaman.getHours(), zaman.getMinutes());
      }
      guven = clock || midnight ? 0.9 : (date || relDays != null) ? 0.65 : period ? 0.6 : 0.25;
    }
  }

  /* ── 5) Görev metni ── */
  // Yan cümlelere böl (. , ; ! ? sonrası); yalnızca rica sözcüklerinden oluşanları at:
  // "Su içmem gerekiyor. Bana bunu hatırlat." → "Su içmem gerekiyor"
  const clauses = [[]];
  for (const t of T) {
    if (!t.used) clauses[clauses.length - 1].push(t.raw);
    if (/[.,;!?…]["'’”]*$/.test(t.raw) && clauses[clauses.length - 1].length) clauses.push([]);
  }
  const isMeta = w => { const n = norm(w); return META_WORDS.has(n) || /^hatırlat/.test(n) || n === ''; };
  let words = [].concat(...clauses.filter(c => c.length && !c.every(isMeta)));
  words = words.filter(w => !ANY_FILLERS.has(norm(w)) && !/^hatırlat/.test(norm(w)));
  const edge = w => EDGE_FILLERS.has(norm(w)) || norm(w) === '';
  while (words.length && edge(words[0])) words.shift();
  while (words.length && edge(words[words.length - 1])) words.pop();
  let gorev = words.join(' ').replace(/^[\s,.;:–—-]+|[\s,.;:!?–—-]+$/g, '').replace(/\s+([,;])/g, '$1').trim();
  if (gorev) gorev = gorev.charAt(0).toLocaleUpperCase(TR) + gorev.slice(1);
  if (!gorev) gorev = 'Hatırlatıcı';
  if (gorev.length > 200) gorev = gorev.slice(0, 200).trim();

  return {
    zaman,
    görev: gorev,
    saatBelirtildiMi,
    güven: Math.round(guven * 100) / 100,
    yarinaAtildi: rolled,
    varsayilanSaat: !saatBelirtildiMi ? pad2(zaman.getHours()) + ':' + pad2(zaman.getMinutes()) : null
  };

  // 12 saat kuralı
  function resolveHour(h, per, implicit) {
    if (h >= 13) return { h };
    switch (per) {
      case 'sabah': return { h: h === 12 ? 0 : h };
      case 'oglen': return { h: h === 12 ? 12 : h <= 5 ? h + 12 : h };
      case 'ogleden': case 'ikindi': case 'aksamustu': return { h: h < 12 ? h + 12 : h };
      case 'aksam': return h === 12 ? { h: 0, nextDay: true } : { h: h < 12 ? h + 12 : h };
      case 'gece':
        if (h === 12 || h === 0) return { h: 0, nextDay: true };
        if (h <= 5) return implicit ? { h } : { h, nextDay: true };
        return { h: h + 12 >= 24 ? h : h + 12 };
      default:
        if (h === 12 || h === 0) return { h };
        if (h >= 1 && h <= 6) return { h: h + 12 };
        return { h }; // 7–11: sabah (geçmişse yukarıda akşama çevrilir)
    }
  }
}

function pad2(n) { return String(n).padStart(2, '0'); }
/** En yakın tam dakikaya yuvarlar; sonuç "şimdi"den önce ya da ona eşit olursa bir dakika ileri alır. */
function roundToMinute(ms, nowMs) {
  let r = Math.round(ms / 60000) * 60000;
  if (nowMs != null && r <= nowMs) r += 60000;
  return new Date(r);
}

/* ── Arayüz yardımcıları (istemci de kullanır) ──────────────── */
const AYLAR = ['Ocak', 'Şubat', 'Mart', 'Nisan', 'Mayıs', 'Haziran', 'Temmuz', 'Ağustos', 'Eylül', 'Ekim', 'Kasım', 'Aralık'];
const GUNLER = ['Pazar', 'Pazartesi', 'Salı', 'Çarşamba', 'Perşembe', 'Cuma', 'Cumartesi'];

/** "Bugün", "Yarın", "Cuma, 27 Kasım" */
function dayLabel(d, now) {
  now = now || new Date();
  const diff = Math.round((startOfDay(d) - startOfDay(now)) / 86400000);
  if (diff === 0) return 'Bugün';
  if (diff === 1) return 'Yarın';
  if (diff === -1) return 'Dün';
  const base = GUNLER[d.getDay()] + ', ' + d.getDate() + ' ' + AYLAR[d.getMonth()];
  return d.getFullYear() !== now.getFullYear() ? base + ' ' + d.getFullYear() : base;
}
function hhmm(d) { return pad2(d.getHours()) + ':' + pad2(d.getMinutes()); }
function fullDate(d) { return GUNLER[d.getDay()] + ', ' + d.getDate() + ' ' + AYLAR[d.getMonth()]; }

/* Göreve göre otomatik emoji (istemci kartları ve sunucu bildirimleri ortak kullanır) */
const EMOJI_RULES = [
  ['💊', /(^|\s)(ilaç|ilac|hap|vitamin|şurup|iğne)/],
  ['🩺', /(^|\s)(doktor|dişçi|diş|hastane|muayene|tahlil|eczane|klinik)/],
  ['✈️', /(^|\s)(uçak|uçuş|havalimanı|havaalanı|uçağ|check-in)/],
  ['📞', /(^|\s)(ara$|ara\s|aran|aray|arama|telefon|tel\s|görüntülü)/],
  ['👥', /(^|\s)(toplantı|görüşme|meeting|sunum|buluş|zoom|teams|mülakat)/],
  ['🏋️', /(^|\s)(spor|koşu|yoga|pilates|antrenman|salon|yürüyüş|gym|fitness|yüzme)/],
  ['🍽️', /(^|\s)(yemek|kahvaltı|akşam yemeği|öğle yemeği|restoran|pişir|fırın|çay|kahve)/],
  ['💧', /(^|\s)(su\s|su$|sula|bardak su)/],
  ['🛒', /(^|\s)(alışveriş|market|süt|ekmek|manav|bakkal|sipariş|kargo)/]
];
function emojiFor(text) {
  const t = lower(text) + ' ';
  for (const [e, re] of EMOJI_RULES) if (re.test(t)) return e;
  return '🔔';
}

/* ════════════════════════════════════════════════════════════════
   Web Push — kütüphanesiz, yalnızca Web Crypto
   • VAPID (RFC 8292): ES256 imzalı JWT
   • Yük şifrelemesi (RFC 8291 + RFC 8188): aes128gcm
   Cloudflare Workers ve Node 20+ ortamında aynı kodla çalışır.
   ════════════════════════════════════════════════════════════════ */

const subtle = () => globalThis.crypto.subtle;
const enc = new TextEncoder();

/* ── base64url ── */
function b64uEncode(buf) {
  const bytes = buf instanceof Uint8Array ? buf : new Uint8Array(buf);
  let s = '';
  for (let i = 0; i < bytes.length; i += 0x8000) s += String.fromCharCode.apply(null, bytes.subarray(i, i + 0x8000));
  return btoa(s).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}
function b64uDecode(str) {
  if (typeof str !== 'string' || !/^[A-Za-z0-9_\-]*={0,2}$/.test(str)) throw new Error('bad_base64');
  const s = str.replace(/-/g, '+').replace(/_/g, '/').replace(/=+$/, '');
  const bin = atob(s + '==='.slice((s.length + 3) % 4));
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}
function concat(...arrs) {
  const len = arrs.reduce((a, b) => a + b.length, 0);
  const out = new Uint8Array(len);
  let o = 0;
  for (const a of arrs) { out.set(a, o); o += a.length; }
  return out;
}

/* ── VAPID anahtarları ── */
async function generateVapidKeys() {
  const kp = await subtle().generateKey({ name: 'ECDSA', namedCurve: 'P-256' }, true, ['sign', 'verify']);
  const raw = new Uint8Array(await subtle().exportKey('raw', kp.publicKey));
  const jwk = await subtle().exportKey('jwk', kp.privateKey);
  return { publicKey: b64uEncode(raw), privateJwk: { kty: jwk.kty, crv: jwk.crv, x: jwk.x, y: jwk.y, d: jwk.d } };
}

/** VAPID JWT üretir. aud = push servisinin origin'i, exp ≤ 12 saat. */
async function vapidJwt(aud, subject, privateJwk, nowSec) {
  const now = nowSec || Math.floor(Date.now() / 1000);
  const header = b64uEncode(enc.encode(JSON.stringify({ typ: 'JWT', alg: 'ES256' })));
  const payload = b64uEncode(enc.encode(JSON.stringify({ aud, exp: now + 12 * 3600, sub: subject })));
  const key = await subtle().importKey('jwk', { ...privateJwk, ext: true, key_ops: ['sign'] }, { name: 'ECDSA', namedCurve: 'P-256' }, false, ['sign']);
  // Web Crypto ECDSA imzası zaten JWS'nin istediği ham r||s (64 bayt) biçimindedir
  const sig = new Uint8Array(await subtle().sign({ name: 'ECDSA', hash: 'SHA-256' }, key, enc.encode(header + '.' + payload)));
  return header + '.' + payload + '.' + b64uEncode(sig);
}

/* ── HKDF (Extract + Expand) ── */
async function hkdf(salt, ikm, info, length) {
  const key = await subtle().importKey('raw', ikm, 'HKDF', false, ['deriveBits']);
  return new Uint8Array(await subtle().deriveBits({ name: 'HKDF', hash: 'SHA-256', salt, info }, key, length * 8));
}

/**
 * RFC 8291 şifreleme. Dönüş: aes128gcm gövdesi (Uint8Array).
 * opts.salt ve opts.asKeys yalnızca test vektörü içindir.
 */
async function encryptPayload(plaintext, uaPublicB64, authSecretB64, opts = {}) {
  const uaPublic = b64uDecode(uaPublicB64);
  const authSecret = b64uDecode(authSecretB64);
  if (uaPublic.length !== 65 || uaPublic[0] !== 4) throw new Error('bad_p256dh');
  if (authSecret.length < 16) throw new Error('bad_auth');
  const data = typeof plaintext === 'string' ? enc.encode(plaintext) : plaintext;
  const rs = 4096;
  if (data.length + 1 + 16 > rs - 86) throw new Error('payload_too_large');

  // Efemer uygulama sunucusu anahtarı
  let asPrivate, asPublic;
  if (opts.asKeys) {
    asPrivate = await subtle().importKey('jwk', opts.asKeys.privateJwk, { name: 'ECDH', namedCurve: 'P-256' }, false, ['deriveBits']);
    asPublic = b64uDecode(opts.asKeys.publicKey);
  } else {
    const kp = await subtle().generateKey({ name: 'ECDH', namedCurve: 'P-256' }, true, ['deriveBits']);
    asPrivate = kp.privateKey;
    asPublic = new Uint8Array(await subtle().exportKey('raw', kp.publicKey));
  }
  const uaKey = await subtle().importKey('raw', uaPublic, { name: 'ECDH', namedCurve: 'P-256' }, false, []);
  const ecdhSecret = new Uint8Array(await subtle().deriveBits({ name: 'ECDH', public: uaKey }, asPrivate, 256));

  // IKM = HKDF(auth_secret, ecdh_secret, "WebPush: info" || 0x00 || ua_public || as_public, 32)
  const keyInfo = concat(enc.encode('WebPush: info\0'), uaPublic, asPublic);
  const ikm = await hkdf(authSecret, ecdhSecret, keyInfo, 32);

  const salt = opts.salt ? b64uDecode(opts.salt) : globalThis.crypto.getRandomValues(new Uint8Array(16));
  const cek = await hkdf(salt, ikm, enc.encode('Content-Encoding: aes128gcm\0'), 16);
  const nonce = await hkdf(salt, ikm, enc.encode('Content-Encoding: nonce\0'), 12);

  // Tek kayıt: düz metin || 0x02 (son kayıt sınırlayıcısı)
  const padded = concat(data, new Uint8Array([2]));
  const aesKey = await subtle().importKey('raw', cek, 'AES-GCM', false, ['encrypt']);
  const ct = new Uint8Array(await subtle().encrypt({ name: 'AES-GCM', iv: nonce, tagLength: 128 }, aesKey, padded));

  // Başlık: salt(16) || rs(4, big-endian) || idlen(1) || keyid(as_public)
  const header = new Uint8Array(16 + 4 + 1 + asPublic.length);
  header.set(salt, 0);
  new DataView(header.buffer).setUint32(16, rs, false);
  header[20] = asPublic.length;
  header.set(asPublic, 21);
  return concat(header, ct);
}

/* ── Güvenlik: yalnızca bilinen push servisleri ── */
function isAllowedEndpoint(endpoint) {
  let u;
  try { u = new URL(endpoint); } catch { return false; }
  if (u.protocol !== 'https:' || u.port || u.username || u.password) return false;
  const h = u.hostname.toLowerCase();
  return h === 'web.push.apple.com' || h.endsWith('.push.apple.com') ||
    h === 'fcm.googleapis.com' ||
    h.endsWith('.push.services.mozilla.com') ||
    h.endsWith('.notify.windows.com');
}

/** Aboneliğin biçimini doğrular. Geçerliyse temizlenmiş kopya döner, değilse null. */
function cleanSubscription(sub) {
  try {
    if (!sub || typeof sub !== 'object' || typeof sub.endpoint !== 'string' || sub.endpoint.length > 2048) return null;
    if (!isAllowedEndpoint(sub.endpoint)) return null;
    const k = sub.keys || {};
    const p = b64uDecode(k.p256dh), a = b64uDecode(k.auth);
    if (p.length !== 65 || p[0] !== 4 || a.length !== 16) return null;
    return { endpoint: sub.endpoint, keys: { p256dh: k.p256dh, auth: k.auth } };
  } catch { return null; }
}

/**
 * Bildirim gönderir. Dönüş: { ok, status, gone, retry }
 *  gone  → abonelik geçersiz (404/410), silinmeli
 *  retry → geçici hata (429/5xx/ağ), sonra tekrar denenmeli
 */
async function sendPush(sub, payloadObj, vapid, fetchImpl) {
  const f = fetchImpl || globalThis.fetch;
  if (!sub || !isAllowedEndpoint(sub.endpoint)) return { ok: false, status: 0, gone: true, retry: false, error: 'endpoint_not_allowed' };
  try {
    const body = await encryptPayload(JSON.stringify(payloadObj), sub.keys.p256dh, sub.keys.auth);
    const aud = new URL(sub.endpoint).origin;
    const jwt = await vapidJwt(aud, vapid.subject, vapid.privateJwk);
    const res = await f(sub.endpoint, {
      method: 'POST',
      headers: {
        'Authorization': `vapid t=${jwt}, k=${vapid.publicKey}`,
        'TTL': '86400',
        'Urgency': 'high',
        'Content-Encoding': 'aes128gcm',
        'Content-Type': 'application/octet-stream'
      },
      body
    });
    const status = res.status;
    if (status >= 200 && status < 300) return { ok: true, status };
    if (status === 404 || status === 410) return { ok: false, status, gone: true, retry: false };
    if (status === 429 || status >= 500) return { ok: false, status, gone: false, retry: true };
    return { ok: false, status, gone: false, retry: true }; // 400/403/413: sınırlı tekrar
  } catch (e) {
    return { ok: false, status: 0, gone: false, retry: true, error: String(e && e.message || e) };
  }
}

async function sha256Hex(str) {
  const h = new Uint8Array(await subtle().digest('SHA-256', enc.encode(str)));
  return Array.from(h, b => b.toString(16).padStart(2, '0')).join('');
}

/* ════════════════════════════════════════════════════════════════
   ANIMSA — Sunucu (Cloudflare Worker)
   • Uygulamayı sunar (HTML, manifest, service worker, ikonlar)
   • JSON API: /api/config, /api/subscribe, /api/reminders, /api/delete, /api/sync, /api/test
   • Cron (her dakika): zamanı gelen hatırlatıcılar için Web Push gönderir
   KV anahtarları:
     vapid        → { publicKey, privateJwk, subject }
     sub:<uid>    → { sub, silent, tz, updatedAt }
     pending      → [{ uid, id, text, at, tries, snoozed }]  (cron yalnızca bunu okur)
   İsteğe bağlı "AI" bağlaması (Workers AI): /api/transcribe ile sesi Whisper'la yazıya çevirir.
   ════════════════════════════════════════════════════════════════ */

const MAX_PENDING = 1000;          // KV değerini makul boyutta tut
const MAX_PER_UID = 300;
const MAX_TRIES = 5;
const MAX_SENDS_PER_RUN = 40;      // ücretsiz plan: çağrı başına 50 alt istek
const EARLY_MS = 15000;            // cron dakika başında çalışır; 15 sn erken gönderim payı
const UID_RE = /^[a-f0-9]{64}$/;
const ID_RE = /^[A-Za-z0-9_-]{8,64}$/;

const SEC_HEADERS = {
  'X-Content-Type-Options': 'nosniff',
  'Referrer-Policy': 'no-referrer',
  'X-Frame-Options': 'DENY'
};
const CSP = "default-src 'self'; script-src 'self' 'unsafe-inline'; style-src 'self' 'unsafe-inline'; img-src 'self' data: blob:; connect-src 'self'; media-src 'self' blob: mediastream:; worker-src 'self'; manifest-src 'self'; frame-ancestors 'none'; base-uri 'none'; form-action 'self'";

function json(obj, status = 200, extra = {}) {
  return new Response(JSON.stringify(obj), {
    status,
    headers: { 'Content-Type': 'application/json; charset=utf-8', 'Cache-Control': 'no-store', ...SEC_HEADERS, ...extra }
  });
}
const err = (status, code, message) => json({ ok: false, error: code, message }, status);

class HttpError extends Error { constructor(status, code, message) { super(message); this.status = status; this.code = code; } }

async function readJson(request) {
  const ct = request.headers.get('content-type') || '';
  if (!ct.includes('application/json')) throw new HttpError(415, 'unsupported_media_type', 'İstek gövdesi JSON olmalı.');
  const text = await request.text();
  if (text.length > 65536) throw new HttpError(413, 'too_large', 'İstek çok büyük.');
  try {
    const data = JSON.parse(text);
    if (!data || typeof data !== 'object' || Array.isArray(data)) throw new Error();
    return data;
  } catch { throw new HttpError(400, 'bad_json', 'Geçersiz JSON.'); }
}

function needUid(uid) { if (typeof uid !== 'string' || !UID_RE.test(uid)) throw new HttpError(400, 'bad_uid', 'Geçersiz kullanıcı kimliği.'); return uid; }
function needId(id) { if (typeof id !== 'string' || !ID_RE.test(id)) throw new HttpError(400, 'bad_id', 'Geçersiz hatırlatıcı kimliği.'); return id; }
function needText(t) {
  if (typeof t !== 'string') throw new HttpError(400, 'bad_text', 'Metin eksik.');
  const s = t.replace(/[\u0000-\u001f\u007f]/g, ' ').trim().slice(0, 300);
  if (!s) throw new HttpError(400, 'bad_text', 'Metin boş olamaz.');
  return s;
}
function needAt(at, now) {
  if (typeof at !== 'number' || !Number.isFinite(at) || !Number.isInteger(at)) throw new HttpError(400, 'bad_at', 'Geçersiz zaman.');
  if (at < now - 10 * 60000) throw new HttpError(400, 'at_in_past', 'Bu zaman geçmişte kaldı.');
  if (at > now + 3 * 365 * 86400000) throw new HttpError(400, 'at_too_far', 'Zaman çok ileride.');
  return at;
}

/* ── KV yardımcıları ── */
async function readPending(env) {
  try {
    const v = await env.KV.get('pending', 'json');
    return Array.isArray(v) ? v.filter(r => r && typeof r.uid === 'string' && typeof r.id === 'string' && typeof r.at === 'number') : [];
  } catch { return []; }
}
async function writePending(env, list) {
  list.sort((a, b) => a.at - b.at);
  await env.KV.put('pending', JSON.stringify(list));
}
async function getSub(env, uid) {
  try { const v = await env.KV.get('sub:' + uid, 'json'); return v && v.sub ? v : null; } catch { return null; }
}

const vapidCache = new WeakMap(); // izolat içi önbellek, KV bağlaması başına (KV okumasını azaltır)
async function getVapid(env, origin) {
  let v = vapidCache.get(env.KV);
  if (!v) {
    v = await env.KV.get('vapid', 'json');
    if (!v || !v.publicKey || !v.privateJwk) {
      // İlk çalışma: anahtar çiftini üret ve sakla
      v = await generateVapidKeys();
      v.createdAt = Date.now();
      await env.KV.put('vapid', JSON.stringify(v));
      const again = await env.KV.get('vapid', 'json'); // eşzamanlı ilk istekler aynı anahtarda buluşsun
      if (again && again.publicKey) v = again;
    }
  }
  if (origin && v.subject !== origin && /^https:\/\//.test(origin)) {
    v = { ...v, subject: origin };
    await env.KV.put('vapid', JSON.stringify(v));
  }
  vapidCache.set(env.KV, v);
  return v;
}
function vapidFor(env, v) {
  return { publicKey: v.publicKey, privateJwk: v.privateJwk, subject: env.VAPID_SUBJECT || v.subject || 'mailto:animsa@localhost' };
}

function validTz(tz) {
  if (typeof tz !== 'string' || tz.length > 64) return null;
  try { new Intl.DateTimeFormat('tr-TR', { timeZone: tz }); return tz; } catch { return null; }
}
function clockIn(at, tz) {
  if (!tz) return '';
  try { return new Intl.DateTimeFormat('tr-TR', { hour: '2-digit', minute: '2-digit', hour12: false, timeZone: tz }).format(new Date(at)); } catch { return ''; }
}
/** Bildirim içeriği: başlıkta emoji + görev (iOS altına zaten "from Anımsa" ekler), gövdede saat */
function payloadFor(r, rec) {
  const text = r.text.length > 90 ? r.text.slice(0, 88).trim() + '…' : r.text;
  const time = clockIn(r.at, rec && rec.tz);
  const body = (r.snoozed ? 'Ertelendi · ' : '') + (time ? time + ' · ' : '') + 'Ertelemek için dokun';
  return { title: emojiFor(r.text) + ' ' + text, body, id: r.id, at: r.at, url: '/?r=' + encodeURIComponent(r.id), silent: !!(rec && rec.silent) };
}

/* ── Ses → yazı (Workers AI / Whisper) ── */
const STT_MAX = 2.5 * 1024 * 1024;
const HALLUCINATIONS = /altyaz[ıi]|abone ol|izlediğiniz için|teşekkürler izlediğiniz|www\.|\.com/i;
function b64std(u8) {
  let s = '';
  for (let i = 0; i < u8.length; i += 0x8000) s += String.fromCharCode.apply(null, u8.subarray(i, i + 0x8000));
  return btoa(s);
}
async function transcribe(env, audio) {
  let out = null, lastErr = null;
  try {
    out = await env.AI.run('@cf/openai/whisper-large-v3-turbo', { audio: b64std(audio), task: 'transcribe', language: 'tr', vad_filter: true });
  } catch (e) { lastErr = e; }
  if (!out || typeof out.text !== 'string') {
    try { out = await env.AI.run('@cf/openai/whisper', { audio: Array.from(audio) }); } catch (e) { lastErr = e; out = null; }
  }
  if (!out || typeof out.text !== 'string') throw lastErr || new Error('stt_failed');
  let text = out.text.replace(/\s+/g, ' ').trim();
  if (HALLUCINATIONS.test(text)) text = '';   // Whisper'ın sessizlikte uydurduğu kalıplar
  return text.slice(0, 300);
}

/* ── API ── */
async function handleApi(request, env, url, deps) {
  const path = url.pathname;
  const now = deps.now();
  if (path === '/api/config') {
    if (request.method !== 'GET') return err(405, 'method_not_allowed', 'Yalnızca GET.');
    const v = await getVapid(env, url.origin);
    return json({ ok: true, publicKey: v.publicKey, ai: !!(env.AI && env.AI.run) });
  }
  if (path === '/api/transcribe') {
    if (request.method !== 'POST') return json({ ok: false, error: 'method_not_allowed', message: 'Yalnızca POST.' }, 405, { Allow: 'POST' });
    if (!env.AI || !env.AI.run) return err(503, 'ai_missing', 'Sesli tanıma için Cloudflare\'de "AI" adlı Workers AI bağlaması gerekli.');
    const ct = request.headers.get('content-type') || '';
    if (!/^audio\//.test(ct)) return err(415, 'unsupported_media_type', 'Ses verisi bekleniyordu.');
    const len = +(request.headers.get('content-length') || 0);
    if (len > STT_MAX) return err(413, 'too_large', 'Kayıt çok uzun.');
    const audio = new Uint8Array(await request.arrayBuffer());
    if (audio.length > STT_MAX) return err(413, 'too_large', 'Kayıt çok uzun.');
    if (audio.length < 2000) return err(400, 'too_short', 'Kayıt çok kısa.');
    try { return json({ ok: true, text: await transcribe(env, audio) }); }
    catch (e) { return err(502, 'stt_failed', 'Ses yazıya çevrilemedi. Biraz sonra tekrar dene.'); }
  }
  const routes = ['/api/subscribe', '/api/reminders', '/api/delete', '/api/sync', '/api/test'];
  if (!routes.includes(path)) return err(404, 'not_found', 'Böyle bir uç nokta yok.');
  if (request.method !== 'POST') return json({ ok: false, error: 'method_not_allowed', message: 'Yalnızca POST.' }, 405, { Allow: 'POST' });
  const body = await readJson(request);

  if (path === '/api/subscribe') {
    const uid = needUid(body.uid);
    const sub = cleanSubscription(body.sub);
    if (!sub) throw new HttpError(400, 'bad_subscription', 'Geçersiz bildirim aboneliği.');
    if ((await sha256Hex(sub.endpoint)) !== uid) throw new HttpError(400, 'uid_mismatch', 'Kimlik abonelikle eşleşmiyor.');
    await env.KV.put('sub:' + uid, JSON.stringify({ sub, silent: body.silent === true, tz: validTz(body.tz), updatedAt: now }));
    // Abonelik yenilendiyse eski kimliğin bekleyenlerini yeni kimliğe taşı
    if (typeof body.oldUid === 'string' && UID_RE.test(body.oldUid) && body.oldUid !== uid) {
      await env.KV.delete('sub:' + body.oldUid);
      const list = await readPending(env);
      if (list.some(r => r.uid === body.oldUid)) {
        list.forEach(r => { if (r.uid === body.oldUid) r.uid = uid; });
        await writePending(env, list);
      }
    }
    return json({ ok: true });
  }

  const uid = needUid(body.uid);

  if (path === '/api/reminders') {
    const id = needId(body.id);
    const text = needText(body.text);
    const at = needAt(body.at, now);
    if (!(await getSub(env, uid))) throw new HttpError(404, 'not_subscribed', 'Bildirim aboneliği bulunamadı.');
    const list = (await readPending(env)).filter(r => !(r.uid === uid && r.id === id));
    if (list.length >= MAX_PENDING || list.filter(r => r.uid === uid).length >= MAX_PER_UID) throw new HttpError(429, 'too_many', 'Çok fazla bekleyen hatırlatıcı var.');
    list.push({ uid, id, text, at, tries: 0, snoozed: body.snoozed === true });
    await writePending(env, list);
    return json({ ok: true });
  }

  if (path === '/api/delete') {
    const list = await readPending(env);
    if (body.all === true) {
      const rest = list.filter(r => r.uid !== uid);
      if (rest.length !== list.length) await writePending(env, rest);
      await env.KV.delete('sub:' + uid);
      return json({ ok: true });
    }
    const id = needId(body.id);
    const rest = list.filter(r => !(r.uid === uid && r.id === id));
    if (rest.length !== list.length) await writePending(env, rest);
    return json({ ok: true, deleted: list.length - rest.length });
  }

  if (path === '/api/sync') {
    // Çevrimdışı kalmış değişiklikleri telafi eder: bu kullanıcının bekleyenlerini istemcinin listesiyle değiştirir
    if (!Array.isArray(body.reminders) || body.reminders.length > MAX_PER_UID) throw new HttpError(400, 'bad_reminders', 'Geçersiz liste.');
    if (!(await getSub(env, uid))) throw new HttpError(404, 'not_subscribed', 'Bildirim aboneliği bulunamadı.');
    const list = await readPending(env);
    const mine = new Map(list.filter(r => r.uid === uid).map(r => [r.id, r]));
    const next = list.filter(r => r.uid !== uid);
    const seen = new Set();
    for (const item of body.reminders) {
      if (!item || typeof item !== 'object') continue;
      const id = needId(item.id), text = needText(item.text);
      if (seen.has(id)) continue; seen.add(id);
      if (typeof item.at !== 'number' || !Number.isInteger(item.at)) throw new HttpError(400, 'bad_at', 'Geçersiz zaman.');
      const old = mine.get(id);
      // Geçmiş zamanlı kayıt sunucuda yoksa ekleme (zaten gönderilmiş olabilir)
      if (item.at <= now && !(old && old.at === item.at)) continue;
      if (item.at > now + 3 * 365 * 86400000) continue;
      next.push({ uid, id, text, at: item.at, tries: old && old.at === item.at ? old.tries || 0 : 0, snoozed: item.snoozed === true });
    }
    if (next.length > MAX_PENDING) throw new HttpError(429, 'too_many', 'Çok fazla bekleyen hatırlatıcı var.');
    const sig = l => JSON.stringify(l.filter(r => r.uid === uid).map(r => [r.id, r.text, r.at]).sort());
    const changed = sig(next) !== sig(list);
    if (changed) await writePending(env, next);
    return json({ ok: true, changed, count: next.filter(r => r.uid === uid).length });
  }

  if (path === '/api/test') {
    const rec = await getSub(env, uid);
    if (!rec) throw new HttpError(404, 'not_subscribed', 'Bildirim aboneliği bulunamadı.');
    const v = vapidFor(env, await getVapid(env));
    const res = await sendPush(rec.sub, { title: '🎉 Test bildirimi', body: 'Her şey yolunda. Hatırlatıcıların böyle görünecek.', id: 'test', at: now, url: '/', silent: rec.silent }, v, deps.fetch);
    if (res.ok) return json({ ok: true });
    if (res.gone) { await env.KV.delete('sub:' + uid); return err(410, 'subscription_gone', 'Abonelik geçersiz; bildirimleri yeniden açın.'); }
    return err(502, 'push_failed', 'Bildirim servisi isteği reddetti (' + res.status + ').');
  }
  return err(404, 'not_found', 'Böyle bir uç nokta yok.');
}

/* ── Zamanlayıcı ── */
async function runCron(env, deps) {
  const now = deps.now();
  const list = await readPending(env);
  const due = list.filter(r => r.at <= now + EARLY_MS).slice(0, MAX_SENDS_PER_RUN);
  if (!due.length) return { sent: 0, failed: 0, dropped: 0, waiting: list.length };

  const v = vapidFor(env, await getVapid(env));
  const subs = new Map();
  const remove = new Set(), bump = new Set(), goneUids = new Set();
  const key = r => r.uid + '|' + r.id + '|' + r.at;
  let sent = 0, failed = 0, dropped = 0;

  for (const r of due) {
    if (goneUids.has(r.uid)) { remove.add(key(r)); dropped++; continue; }
    if (!subs.has(r.uid)) subs.set(r.uid, await getSub(env, r.uid));
    const rec = subs.get(r.uid);
    if (!rec) { remove.add(key(r)); dropped++; continue; }           // abonelik yok → gönderilemez
    const res = await sendPush(rec.sub, payloadFor(r, rec), v, deps.fetch);
    if (res.ok) { remove.add(key(r)); sent++; }
    else if (res.gone) { goneUids.add(r.uid); remove.add(key(r)); dropped++; await env.KV.delete('sub:' + r.uid); }
    else if ((r.tries || 0) + 1 >= MAX_TRIES) { remove.add(key(r)); dropped++; }
    else { bump.add(key(r)); failed++; }
  }

  // Yazmadan hemen önce tazeden oku (bu arada eklenen kayıtlar kaybolmasın)
  const fresh = await readPending(env);
  const next = [];
  for (const r of fresh) {
    const k = key(r);
    if (remove.has(k) || goneUids.has(r.uid)) continue;
    if (bump.has(k)) next.push({ ...r, tries: (r.tries || 0) + 1 });
    else next.push(r);
  }
  await writePending(env, next);
  return { sent, failed, dropped, waiting: next.length };
}

/* ── Statik dosyalar ── */
function staticResponse(path, assets, method) {
  const map = {
    '/': ['html', 'text/html; charset=utf-8', 'no-cache'],
    '/index.html': ['html', 'text/html; charset=utf-8', 'no-cache'],
    '/sw.js': ['sw', 'text/javascript; charset=utf-8', 'no-cache'],
    '/manifest.webmanifest': ['manifest', 'application/manifest+json; charset=utf-8', 'no-cache'],
    '/icon-180.png': ['icon180', 'image/png', 'public, max-age=604800'],
    '/apple-touch-icon.png': ['icon180', 'image/png', 'public, max-age=604800'],
    '/icon-192.png': ['icon192', 'image/png', 'public, max-age=604800'],
    '/icon-512.png': ['icon512', 'image/png', 'public, max-age=604800'],
    '/favicon.ico': ['icon192', 'image/png', 'public, max-age=604800']
  };
  const m = map[path];
  if (!m) return null;
  const headers = { 'Content-Type': m[1], 'Cache-Control': m[2], ...SEC_HEADERS };
  if (m[0] === 'html') { headers['Content-Security-Policy'] = CSP; headers['Permissions-Policy'] = 'microphone=(self)'; }
  if (m[0] === 'sw') headers['Service-Worker-Allowed'] = '/';
  return new Response(method === 'HEAD' ? null : assets.get(m[0]), { status: 200, headers });
}

/* ── Worker girişi ── */
function makeWorker(ASSETS) {
  const cache = new Map();
  const assets = {
    get(name) {
      if (!cache.has(name)) {
        const v = ASSETS[name];
        if (name.startsWith('icon')) { const bin = atob(v); const u = new Uint8Array(bin.length); for (let i = 0; i < bin.length; i++) u[i] = bin.charCodeAt(i); cache.set(name, u); }
        else cache.set(name, v);
      }
      return cache.get(name);
    }
  };
  const defaultDeps = () => ({ now: () => Date.now(), fetch: (...a) => fetch(...a) });

  return {
    async fetch(request, env, ctx, deps) {
      deps = deps || defaultDeps();
      try {
        const url = new URL(request.url);
        if (url.pathname.startsWith('/api/')) {
          if (!env || !env.KV) return err(500, 'kv_missing', 'KV bağlaması bulunamadı. Worker ayarlarında "KV" adıyla bir KV ad alanı bağlayın.');
          return await handleApi(request, env, url, deps);
        }
        if (request.method !== 'GET' && request.method !== 'HEAD') return new Response('Yöntem desteklenmiyor', { status: 405, headers: { Allow: 'GET, HEAD', ...SEC_HEADERS } });
        const res = staticResponse(url.pathname, assets, request.method);
        if (res) return res;
        return new Response('Sayfa bulunamadı', { status: 404, headers: { 'Content-Type': 'text/plain; charset=utf-8', ...SEC_HEADERS } });
      } catch (e) {
        if (e instanceof HttpError) return err(e.status, e.code, e.message);
        return err(500, 'server_error', 'Sunucuda beklenmeyen bir hata oluştu.');
      }
    },
    async scheduled(event, env, ctx, deps) {
      if (!env || !env.KV) return;
      const p = runCron(env, deps || defaultDeps()).catch(e => console.log('cron hata', e && e.message));
      if (ctx && ctx.waitUntil) ctx.waitUntil(p); else await p;
    }
  };
}


